arguments.new_string:
while stack:
    parent, ch = stack.pop()
    child = parent.children[ch]
    if not child.children and not child.is_end:
        del parent.children[ch]
    else:
        break

arguments.old_string:
while stack:
    parent, ch = stack.pop()
    child = parent.children[ch]
    if not child.children:
        del parent.children[ch]
    else:
        break
